import{c as t,Q as a,j as s,m as r}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"SIA: Self Improving AI with Harness & Weight Updates","description":"","frontmatter":{"url":"https://arxiv.org/abs/2605.27276","title":"SIA: Self Improving AI with Harness & Weight Updates","archived_date":"2026-06-14T00:00:00.000Z","arxiv_id":2605.27276,"authors":["Prannay Hebbar","Yogendra Manawat","Samuel Verboomen","Alesia Ivanova","Selvam Palanimalai","Kunal Bhatia","Vignesh Baskaran"],"domains":["self-improving-agents","harness-engineering","test-time-training","reinforcement-learning"],"pdf_path":"pdfs/2605.27276.pdf","published_date":"2026-05-26T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-05-26-sia-self-improving-ai-harness-weight-updates-2605-27276.md","filePath":"research/papers/2026-05-26-sia-self-improving-ai-harness-weight-updates-2605-27276.md","lastUpdated":1785909234000}'),o={name:"research/papers/2026-05-26-sia-self-improving-ai-harness-weight-updates-2605-27276.md"};function i(n,e,d,l,h,c){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="sia-self-improving-ai-with-harness-weight-updates" tabindex="-1">SIA: Self Improving AI with Harness &amp; Weight Updates <a class="header-anchor" href="#sia-self-improving-ai-with-harness-weight-updates" aria-label="Permalink to &quot;SIA: Self Improving AI with Harness &amp; Weight Updates&quot;">​</a></h1><p><strong>Authors</strong>: Prannay Hebbar, Yogendra Manawat, Samuel Verboomen, Alesia Ivanova, Selvam Palanimalai, Kunal Bhatia, Vignesh Baskaran<br><strong>Published</strong>: May 26 2026 (v1); revised May 28 2026 (v2)<br><strong>Source</strong>: <a href="https://arxiv.org/abs/2605.27276" target="_blank" rel="noreferrer">https://arxiv.org/abs/2605.27276</a><br><strong>arXiv ID</strong>: 2605.27276<br><strong>Categories</strong>: cs.AI, cs.CL</p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>Humans are the bottleneck in building and improving AI. Two largely disjoint research silos exist: the harness-update school (meta-agent rewrites scaffold while weights are fixed) and the test-time training school (RL pipeline updates model weights while harness is fixed). SIA proposes a self-improving loop in which a Feedback-Agent updates <strong>both</strong> the harness and the weights of a task-specific agent. Evaluated across three contrasting domains: Chinese legal charge classification (LawBench), low-level GPU kernel optimisation (AlphaEvolve TriMul), and single-cell RNA denoising (MAGIC scRNA-seq). SIA-W+H (harness + weight updates) outperforms SIA-H (harness only) on all three benchmarks.</p><hr><h2 id="core-architecture" tabindex="-1">Core Architecture <a class="header-anchor" href="#core-architecture" aria-label="Permalink to &quot;Core Architecture&quot;">​</a></h2><h3 id="two-lever-loop" tabindex="-1">Two-Lever Loop <a class="header-anchor" href="#two-lever-loop" aria-label="Permalink to &quot;Two-Lever Loop&quot;">​</a></h3><p>SIA operates three LLM components in a step-budget loop:</p><ol><li><strong>Meta-Agent</strong> — Initialises the first scaffold from task specification and reference implementations.</li><li><strong>Task-Specific Agent</strong> — Executes against dataset inside a sandbox; produces trajectory.</li><li><strong>Feedback-Agent</strong> — Reads trajectory, selects at each step between two actions: <ul><li><strong>Harness update</strong>: scaffold evolution (prompts/tools/retry logic/parsing), weights fixed.</li><li><strong>Weight update</strong>: RL-based LoRA update, scaffold fixed.</li></ul></li></ol><p>The Feedback-Agent&#39;s action selection is dynamic, conditioned on observed reward landscape (density, rollout cost, pass-rate distribution, regression risk). The two levers are interleaved freely, not locked into sequential phases.</p><h3 id="harness-update-recurrence" tabindex="-1">Harness Update Recurrence <a class="header-anchor" href="#harness-update-recurrence" aria-label="Permalink to &quot;Harness Update Recurrence&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A_{g+1} = F(A_g, τ_g(π_θ), E_g, U)</span></span></code></pre></div><p>Where <code>τ_g(π_θ)</code> = full trajectory (prompt, model response, tool call, tool result, extracted answer for every instance). Feedback-Agent diagnoses failure modes from full trajectory, not summary statistics.</p><h3 id="weight-update-algorithms-feedback-agent-selects-per-task" tabindex="-1">Weight Update Algorithms (Feedback-Agent selects per task) <a class="header-anchor" href="#weight-update-algorithms-feedback-agent-selects-per-task" aria-label="Permalink to &quot;Weight Update Algorithms (Feedback-Agent selects per task)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Algorithm</th><th>When selected</th></tr></thead><tbody><tr><td><strong>GRPO</strong></td><td>Rollouts cheap to sample; verifier fires at episode end (classification, short-answer, unit-test). Advantages normalised within rollout group of size G: <code>Â_i = (r_i − r̄)/σ_r</code>. No value network.</td></tr><tr><td><strong>PPO with GAE</strong></td><td>Dense step-level rewards; training stability is binding constraint (multi-step tool-use, long code-generation). Clipped surrogate with value head.</td></tr><tr><td><strong>Entropic advantage weighting</strong></td><td>Heavily right-skewed reward histogram (rare correct solutions). Gradient mass via softmax with adaptive temperature β: <code>w_i ∝ exp(r_i/β)</code>.</td></tr><tr><td><strong>REINFORCE + KL-to-base</strong></td><td>Dense reward; primary risk is capability regression. No critic, no grouping; KL penalty <code>α KL(π_θ ‖ π_θ₀)</code>.</td></tr><tr><td><strong>Best-of-N behavioural cloning</strong></td><td>Cold-start: <code>E[r] ≈ 0</code> across all rollouts. Top-k rollouts distilled via cross-entropy to raise baseline pass rate before RL phase.</td></tr><tr><td><strong>DPO</strong></td><td>Verifier ranks but cannot score absolutely. Ordinal signal without reward model.</td></tr></tbody></table><p>Base model throughout: <code>gpt-oss-120b</code> (internal 120B instruction-tuned). LoRA rank 32 on H100 via Modal. Meta-Agent and Feedback-Agent use <strong>Claude Sonnet 4.6</strong>.</p><hr><h2 id="experimental-results" tabindex="-1">Experimental Results <a class="header-anchor" href="#experimental-results" aria-label="Permalink to &quot;Experimental Results&quot;">​</a></h2><h3 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Task</th><th>Domain</th><th>Metric</th><th>Previous SOTA</th></tr></thead><tbody><tr><td>LawBench (191-class)</td><td>Chinese legal</td><td>top-1 accuracy</td><td>0.450</td></tr><tr><td>AlphaEvolve TriMul</td><td>GPU kernel</td><td>1500/runtime (higher = faster)</td><td>1.292</td></tr><tr><td>MAGIC scRNA-seq</td><td>Single-cell RNA</td><td>mse_norm ∈ [0,1] (higher = better)</td><td>0.240</td></tr></tbody></table><h3 id="ablation-sia-h-vs-sia-w-h" tabindex="-1">Ablation: SIA-H vs SIA-W+H <a class="header-anchor" href="#ablation-sia-h-vs-sia-w-h" aria-label="Permalink to &quot;Ablation: SIA-H vs SIA-W+H&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Task</th><th>Initial</th><th>Prev. SOTA</th><th>SIA-H (harness only)</th><th>SIA-W+H (harness + weights)</th></tr></thead><tbody><tr><td>LawBench (top-1 acc)</td><td>13.5%</td><td>45.0%</td><td>50.0%</td><td><strong>70.1%</strong> (+20.1 pp over SIA-H)</td></tr><tr><td>AlphaEvolve TriMul (reward)</td><td>0.105</td><td>1.292</td><td>0.120 (12,483 μs)</td><td><strong>1.475</strong> (1,017 μs; 91.9% runtime reduction)</td></tr><tr><td>Denoising (mse_norm)</td><td>0.048</td><td>0.240</td><td>0.241</td><td><strong>0.289</strong> (+20% over SIA-H)</td></tr></tbody></table><p>Over initial baseline: +56.6% on LawBench, 91.9% runtime reduction on GPU kernels (14.02× final speedup), +502% on denoising.</p><h3 id="per-domain-analysis" tabindex="-1">Per-Domain Analysis <a class="header-anchor" href="#per-domain-analysis" aria-label="Permalink to &quot;Per-Domain Analysis&quot;">​</a></h3><p><strong>LawBench</strong>: Harness converged at 50.0% (TF-IDF + LinearSVC pipeline, iterative n-gram/regulariser tuning). Feedback-Agent switched to GRPO for the 191-class charge taxonomy; gradient pressure sharpened disambiguation of adjacent charge categories. Final 70.1%.</p><p><strong>AlphaEvolve TriMul</strong>: Harness converged at 12,483 μs (1.14× speedup) via compilation-error parser and timing harness. Feedback-Agent applied GRPO with entropic utility objective (up-weights high-reward rollouts, discounts near-zero noise). Weights internalised H100-specific patterns (shared-memory tiling, fp32 register accumulation, block-size selection) unreachable by scaffold. Final 1,017 μs (14.02×).</p><p><strong>MAGIC scRNA-seq</strong>: Harness swept coupled hyperparameter space (k, t, α), plateaued at mse_norm 0.241. First weight-update checkpoint introduced <code>np.clip + np.rint</code> post-processing — a biological invariant (non-negative integer counts) the scaffold never proposed across all iterations. Final 0.289.</p><hr><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><h3 id="what-each-lever-changes" tabindex="-1">What Each Lever Changes <a class="header-anchor" href="#what-each-lever-changes" aria-label="Permalink to &quot;What Each Lever Changes&quot;">​</a></h3><p><strong>Harness updates</strong> → externalised changes: new tools, tighter parsers, search procedures, retry policies, prompt structure. All gains come from how the scaffold mediates between model and task environment; model checkpoint unchanged.</p><p><strong>Weight updates</strong> → internalised knowledge: domain-specific patterns encoded into parameters unreachable by any scaffold edit. Emerges from direct gradient pressure on task verifier, not from human-authored instruction.</p><p>&quot;The harness shapes how the agent searches; weight updates change what the model knows.&quot;</p><h3 id="feedback-agent-lever-selection-logic" tabindex="-1">Feedback-Agent Lever Selection Logic <a class="header-anchor" href="#feedback-agent-lever-selection-logic" aria-label="Permalink to &quot;Feedback-Agent Lever Selection Logic&quot;">​</a></h3><p>The Feedback-Agent does not run a fixed RL procedure. At each weight-update step it selects algorithm conditioned on: reward density, rollout cost, pass-rate distribution, risk of capability regression. Selection is made at runtime from observed trajectory, not hard-coded by system designer.</p><h3 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h3><p><strong>Coupled co-evolutionary Goodhart</strong>: Harness search and RL weight updates both optimise against the same fixed verifier <code>V</code>. The joint fixed point is a Nash equilibrium between two optimisers blind to each other&#39;s update history — not a global optimiser of <code>V</code>. This can produce systems that appear strong on training verifier but are fragile under perturbation to either component. Standard Goodhart analyses assume a single optimiser; this two-lever setting produces a coupled variant.</p><hr><h2 id="comparison-harness-only-vs-weight-update-schools" tabindex="-1">Comparison: Harness-Only vs Weight-Update Schools <a class="header-anchor" href="#comparison-harness-only-vs-weight-update-schools" aria-label="Permalink to &quot;Comparison: Harness-Only vs Weight-Update Schools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>System</th><th>Edits harness</th><th>Edits weights</th></tr></thead><tbody><tr><td><strong>SIA (ours)</strong></td><td>Yes</td><td>Yes</td></tr><tr><td>Hyperagents (Zhang et al., 2026)</td><td>Yes</td><td>No</td></tr><tr><td>Darwin Gödel Machine (Zhang et al., 2025)</td><td>Yes</td><td>No</td></tr><tr><td>Meta-Harness (Lee et al., 2026)</td><td>Yes</td><td>No</td></tr><tr><td>TTRL (Zuo et al., 2025)</td><td>No</td><td>Yes</td></tr><tr><td>Discover-TTT</td><td>No</td><td>Yes</td></tr><tr><td>EUREKA (Ma et al., 2023)</td><td>Partial</td><td>Yes</td></tr></tbody></table><p>SIA is the only system that updates both scaffold and weights in a single self-improving loop.</p><hr><h2 id="key-quotes" tabindex="-1">Key Quotes <a class="header-anchor" href="#key-quotes" aria-label="Permalink to &quot;Key Quotes&quot;">​</a></h2><blockquote><p>&quot;Harness updates make the model agentic, shaping how it searches and acts, while weight updates build the domain intuition that no prompt or scaffold can instil.&quot;</p></blockquote><blockquote><p>&quot;Scaffold edits concentrate on software-engineering hygiene — parsing, retries, dispatch — and rarely deliver domain-specific reasoning that the base model could not produce given any prompt.&quot;</p></blockquote><blockquote><p>&quot;The Feedback-Agent dynamically selects between scaffold and weight updates in a closed feedback loop, with each update type informed by trajectories produced under the current state of both components.&quot;</p></blockquote><hr><h2 id="related-work-connections" tabindex="-1">Related Work Connections <a class="header-anchor" href="#related-work-connections" aria-label="Permalink to &quot;Related Work Connections&quot;">​</a></h2><ul><li><strong>Meta-Harness</strong> (2603.28052): SIA harness update step is closest in spirit; difference = SIA follows harness convergence with weight updates rather than further mutation.</li><li><strong>Hyperagents</strong> (2603.19461): Closest concurrent work; adds expressivity to scaffold edits but leaves weights fixed. SIA adds weight lever.</li><li><strong>TTRL</strong> (Zuo et al., 2025): RL on unlabelled test data; single-prompt, single-response, no scaffold.</li><li><strong>Discover-TTT</strong> (Yuksekgonul et al., 2026): Entropic utility objective reused by SIA for weight updates.</li></ul>',50)])])}const u=t(o,[["render",i]]);export{g as __pageData,u as default};
